                  match={match}
                  matchIndex={matchIndex}
                  playerIndex={playerIndex as 0 | 1}
                />
              ))}
            </tbody>
          ))}
        </table>
      ))}
    </section>
  );
}

interface MatchPlayerRowProps {
  readonly match: TournamentMatch;
  readonly matchIndex: number;
  readonly playerIndex: 0 | 1;
}

