  border-bottom: 1px solid var(--border);
  text-align: left;
  vertical-align: top;
}
.tournament-table thead th {
  color: var(--secondary);
  font-weight: 600;
}
.tournament-table tbody + tbody tr:first-child > * {
  border-top: 1px solid var(--border);
}
.tournament-table .current-match {
  background: #1b2034;
}
.tournament-champion {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 20px;
  margin: 12px 0 20px;
  padding: 16px;
  border: 1px solid var(--green);
  border-radius: 12px;
  background: var(--panel);
}
.tournament-champion p {
  flex: 1 1 200px;
  font-size: 20px;
}
.tournament-json {
  display: block;
  width: 100%;
  min-height: 220px;
  margin: 8px 0 12px;
  resize: vertical;
  font-family: ui-monospace, monospace;
}
.tournament-storage-warning {
  margin-bottom: 12px;
  color: var(--secondary);
}
.tournament-history ol {
  margin: 0;
  padding-left: 24px;
}
.tournament-history li + li {
  margin-top: 8px;
}
.tournament-history details {
  padding: 8px 0;
}
.tournament-history summary {
  min-height: 44px;
  padding: 10px 0;
  cursor: pointer;
}
.tournament-dialog {
  width: min(440px, calc(100% - 32px));
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: 12px;
  color: var(--text);
  background: var(--panel);
}
.tournament-dialog::backdrop {
  background: rgb(0 0 0 / 70%);
}
.tournament-dialog p {
  margin-bottom: 16px;
}
@media (max-width: 599px) {
  .tournament-setup,
  .tournament-play,
  .tournament-exchange,
  .tournament-history {
    padding: 12px;
  }
  .tournament-name-field {
    align-items: flex-start;
    flex-direction: column;
    gap: 4px;
  }
  .tournament-name-field label {
    flex-basis: auto;
  }
  .tournament-actions .control,
  .tournament-action-row .control {
    flex: 1 1 130px;
  }
}

