 60	export function normalizeName(value: string): string {
 61	  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
 62	}
 63	
 64	export function acceptPlayerNames(drafts: readonly string[], count: number): NameAcceptance {
 65	  if (!isPlayerCount(count) || drafts.length < count) return { error: 'Use 2 to 20 characters.' };
 66	  const names = drafts.slice(0, count).map(normalizeName);
 67	  if (names.some((name) => {
 68	    const length = Array.from(name).length;
 69	    return length < 2 || length > 20;
 70	  }))
 71	    return { error: 'Use 2 to 20 characters.' };
 72	  const folded = names.map((name) => name.toLowerCase());
 73	  if (new Set(folded).size !== folded.length) return { error: 'Each name must be different.' };
 74	  return { names };
 75	}
