 81	export function roundDefinitions(count: TournamentPlayerCount): readonly RoundDefinition[] {
 82	  return count === 4
 83	    ? [
 84	        { name: 'Semifinal', size: 6, matchCount: 2 },
 85	        { name: 'Final', size: 8, matchCount: 1 },
 86	      ]
 87	    : [
 88	        { name: 'Quarterfinal', size: 4, matchCount: 4 },
 89	        { name: 'Semifinal', size: 6, matchCount: 2 },
 90	        { name: 'Final', size: 8, matchCount: 1 },
 91	      ];
 92	}
