102	): Tournament | null {
103	  const accepted = acceptPlayerNames(names, playerCount);
104	  if (!('names' in accepted)) return null;
105	  const entrants = accepted.names.map((name, index) => ({ name, seed: index + 1 }));
106	  const definitions = roundDefinitions(playerCount);
107	  const neededCodes = definitions.reduce((sum, round) => sum + round.matchCount, 0);
108	  if (boardCodes.length !== neededCodes || new Set(boardCodes).size !== boardCodes.length) return null;
109	  let codeIndex = 0;
110	  const rounds = definitions.map((definition, roundIndex): TournamentRound => {
111	    const matches = Array.from({ length: definition.matchCount }, (_, matchIndex) => {
112	      const boardCode = boardCodes[codeIndex++];
113	      const parsed = boardCode ? parseBoardCode(boardCode) : null;
114	      if (!boardCode || !parsed || parsed.size !== definition.size) throw new Error('Invalid tournament deal.');
115	      const seeds = roundIndex === 0 ? openingSeedPairs(playerCount)[matchIndex] : null;
116	      return {
117	        boardCode,
118	        players: seeds
119	          ? [entrantAt(entrants, seeds[0]), entrantAt(entrants, seeds[1])]
120	          : [null, null],
121	        results: [null, null],
122	        winner: null,
123	      } as const;
124	    });
125	    return { matches, name: definition.name, size: definition.size };
126	  });
127	  return { champion: null, current: { round: 0, match: 0, turn: 0 }, entrants, playerCount, rounds, status: 'active' };
128	}
