147	export function compareResults(
148	  firstPlayer: TournamentPlayer,
149	  first: TournamentResult,
150	  secondPlayer: TournamentPlayer,
151	  second: TournamentResult,
152	): TournamentPlayer {
153	  if (first.moves !== second.moves) return first.moves < second.moves ? firstPlayer : secondPlayer;
154	  if (first.elapsedMs !== second.elapsedMs)
155	    return first.elapsedMs < second.elapsedMs ? firstPlayer : secondPlayer;
156	  return firstPlayer.seed > secondPlayer.seed ? firstPlayer : secondPlayer;
157	}
158	
159	export function recordTournamentResult(
160	  tournament: Tournament,
161	  result: TournamentResult,
162	): Tournament {
163	  const position = tournament.current;
164	  const match = currentMatch(tournament);
165	  if (!position || !match || tournament.status !== 'active' || match.results[position.turn]) return tournament;
166	  if (
167	    !Number.isSafeInteger(result.moves) ||
168	    result.moves < tournament.rounds[position.round]!.size ** 2 / 2 ||
169	    result.moves > MOVES_MAX ||
170	    !Number.isFinite(result.elapsedMs) ||
171	    result.elapsedMs < 0 ||
172	    result.elapsedMs > ELAPSED_MAX_MS
173	  )
174	    return tournament;
175	  const results = [...match.results] as [TournamentResult | null, TournamentResult | null];
176	  results[position.turn] = result;
177	  if (!results[0] || !results[1]) return updateMatch(tournament, position, { ...match, results });
178	
179	  const first = match.players[0];
180	  const second = match.players[1];
181	  if (!first || !second) return tournament;
182	  const winner = compareResults(first, results[0], second, results[1]);
183	  const updatedMatch = { ...match, results, winner };
184	  const updatedRounds = replaceMatch(tournament.rounds, position, updatedMatch);
185	  const isFinal = position.round === tournament.rounds.length - 1;
186	  if (isFinal)
187	    return { ...tournament, champion: winner, current: null, rounds: updatedRounds, status: 'complete' };
188	  const nextRound = updatedRounds[position.round + 1];
189	  const nextMatchIndex = Math.floor(position.match / 2);
190	  const nextMatch = nextRound?.matches[nextMatchIndex];
191	  if (!nextRound || !nextMatch) return tournament;
192	  const players = [...nextMatch.players] as [TournamentPlayer | null, TournamentPlayer | null];
193	  players[position.match % 2] = winner;
194	  const advancedRound = {
195	    ...nextRound,
196	    matches: nextRound.matches.map((item, index) => (index === nextMatchIndex ? { ...item, players } : item)),
197	  };
198	  return {
199	    ...tournament,
200	    rounds: updatedRounds.map((round, index) => (index === position.round + 1 ? advancedRound : round)),
201	  };
202	}
203	
204	export function advanceTournamentTurn(tournament: Tournament): Tournament {
205	  const position = tournament.current;
206	  const match = currentMatch(tournament);
207	  if (!position || position.turn !== 0 || !match?.results[0] || match.results[1]) return tournament;
208	  return { ...tournament, current: { ...position, turn: 1 } };
209	}
210	
211	export function advanceTournamentMatch(tournament: Tournament): Tournament {
212	  const position = tournament.current;
213	  const match = currentMatch(tournament);
214	  if (!position || !match?.winner || tournament.status !== 'active') return tournament;
215	  const currentFlatIndex = flatIndex(tournament.rounds, position.round, position.match);
216	  let nextFlatIndex = 0;
217	  for (let round = 0; round < tournament.rounds.length; round += 1) {
218	    for (let index = 0; index < tournament.rounds[round]!.matches.length; index += 1) {
219	      if (nextFlatIndex === currentFlatIndex + 1)
220	        return { ...tournament, current: { round, match: index, turn: 0 } };
221	      nextFlatIndex += 1;
222	    }
223	  }
224	  return tournament;
225	}
226	
227	function entrantAt(entrants: readonly TournamentPlayer[], seed: number): TournamentPlayer {
228	  const entrant = entrants[seed - 1];
229	  if (!entrant) throw new Error('Invalid tournament seed.');
230	  return entrant;
231	}
232	
233	function updateMatch(tournament: Tournament, position: TournamentPosition, match: TournamentMatch): Tournament {
234	  return { ...tournament, rounds: replaceMatch(tournament.rounds, position, match) };
235	}
236	
237	function replaceMatch(
238	  rounds: readonly TournamentRound[],
239	  position: TournamentPosition,
240	  match: TournamentMatch,
241	): readonly TournamentRound[] {
242	  return rounds.map((round, index) =>
243	    index === position.round
244	      ? { ...round, matches: round.matches.map((item, matchIndex) => (matchIndex === position.match ? match : item)) }
245	      : round,
246	  );
247	}
248	
249	function flatIndex(rounds: readonly TournamentRound[], targetRound: number, targetMatch: number): number {
250	  let index = targetMatch;
251	  for (let round = 0; round < targetRound; round += 1) index += rounds[round]!.matches.length;
252	  return index;
253	}

