import { useCallback, useEffect, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { parseBoardCode } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { decodeTournament, encodeTournament, TOURNAMENT_MAX_BYTES } from './tournament-format.ts';
import {
  acceptPlayerNames,
  advanceTournamentMatch,
  advanceTournamentTurn,
  createTournament,
  currentMatch,
  currentPlayer,
  currentResult,
  roundDefinitions,
  type Tournament,
  type TournamentDraft,
  type TournamentResult,
} from './tournament.ts';
import { recordTournamentResult } from './tournament-results.ts';
import {
  browserTournamentStore,
  readTournamentHistory,
  writeTournamentHistory,
  type TournamentStore,
} from './tournament-storage.ts';
import type { TournamentTurnHandle } from './TournamentTurn.tsx';

export type TournamentDialogAction = 'leave' | 'load' | null;

export interface TournamentController {
  readonly actionLabel: string | null;
  readonly activeTurnKey: string;
  readonly autoFocusBoard: boolean;
  readonly current: Tournament['current'];
  readonly dialogAction: TournamentDialogAction;
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly history: readonly Tournament[];
  readonly json: string;
  readonly match: ReturnType<typeof currentMatch>;
  readonly notice: string;
  readonly player: Tournament['entrants'][number] | null;
  readonly result: TournamentResult | null;
  readonly setDraft: Dispatch<SetStateAction<TournamentDraft>>;
  readonly setJson: Dispatch<SetStateAction<string>>;
  readonly startButtonVisible: boolean;
  readonly status: string;
  readonly statusKey: string;
  readonly storageAvailable: boolean;
  readonly tournament: Tournament | null;
  readonly turn: React.RefObject<TournamentTurnHandle | null>;
  readonly turnStarted: boolean;
  cancelDialog(): void;
  confirmDialog(): void;
  exportCurrent(): void;
  loadFromJson(): void;
  onBoardFocused(): void;
  onComplete(result: TournamentResult): void;
  onFeedback(text: string, number: number): void;
  requestLeave(): void;
  startTournament(): void;
  turnAction(): void;
}

interface GameFeedback {
  readonly key: string;
  readonly number: number;
  readonly text: string;
}

interface TournamentNotice {
  readonly message: string;
  readonly number: number;
}

const EMPTY_DRAFT: TournamentDraft = { playerCount: 4, players: ['', '', '', '', '', '', '', ''] };

export function useTournament(onBack: () => void): TournamentController {
  const [store] = useState<TournamentStore | null>(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly Tournament[]>(initialHistory.items);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const [draft, setDraft] = useState<TournamentDraft>(EMPTY_DRAFT);
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [gameSnapshot, setGameSnapshot] = useState<string | null>(null);
  const [turnStarted, setTurnStarted] = useState(false);
  const [startButtonVisible, setStartButtonVisible] = useState(false);
  const [autoFocusBoard, setAutoFocusBoard] = useState(false);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState<TournamentNotice>({ message: '', number: 0 });
  const [gameFeedback, setGameFeedback] = useState<GameFeedback>({ key: '', number: 0, text: '' });
  const [saveWhenComplete, setSaveWhenComplete] = useState(false);
  const [dialogAction, setDialogAction] = useState<TournamentDialogAction>(null);
  const [pendingTransfer, setPendingTransfer] = useState<ReturnType<typeof decodeTournament>>(null);
  const turn = useRef<TournamentTurnHandle>(null);
  const turnKeyRef = useRef('');

  useEffect(() => {
    if (!saveWhenComplete || tournament?.status !== 'complete') return;
    const next = [tournament, ...history].slice(0, 10);
    setHistory(next);
    setStorageAvailable(writeTournamentHistory(store, next));
    setSaveWhenComplete(false);
  }, [history, saveWhenComplete, store, tournament]);

  const current = tournament?.current ?? null;
  const match = tournament ? currentMatch(tournament) : null;
  const player = tournament ? currentPlayer(tournament) : null;
  const result = tournament ? currentResult(tournament) : null;
  const activeTurnKey = current ? `${current.round}-${current.match}-${current.turn}` : '';
  turnKeyRef.current = activeTurnKey;

  const onFeedback = useCallback((text: string, number: number) => {
    setGameFeedback({ key: turnKeyRef.current, number, text });
    setNotice((previous) => ({ ...previous, message: '' }));
  }, []);

  function publish(message: string): void {
    setNotice((previous) => ({ message, number: previous.number + 1 }));
  }

  function clearNotice(): void {
    setNotice((previous) => ({ ...previous, message: '' }));
  }

  function startTournament(): void {
    const accepted = acceptPlayerNames(draft.players, draft.playerCount);
    if (!('names' in accepted)) {
      publish(accepted.error);
      return;
    }
    const sizes = roundDefinitions(draft.playerCount).flatMap((round) =>
      Array.from({ length: round.matchCount }, () => round.size),
    );
    const boardCodes: string[] = [];
    const usedCodes = new Set<string>();
    let previousSeed: number | undefined;
    for (const size of sizes) {
      let code = freshBoardCode(size, previousSeed);
      while (usedCodes.has(code)) code = freshBoardCode(size, previousSeed);
      usedCodes.add(code);
      boardCodes.push(code);
      previousSeed = parseBoardCode(code)?.seed;
    }
    const next = createTournament(draft.playerCount, accepted.names, boardCodes);
    if (!next) {
      publish('Could not start tournament.');
      return;
    }
    const players = [...draft.players];
    accepted.names.forEach((name, index) => { players[index] = name; });
    setDraft({ ...draft, players });
    setTournament(next);
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setSaveWhenComplete(true);
    clearNotice();
    setGameFeedback({ key: '', number: 0, text: '' });
  }

  function startTurn(): void {
    setGameSnapshot(null);
    setTurnStarted(true);
    setStartButtonVisible(true);
    setAutoFocusBoard(true);
    clearNotice();
  }

  function onBoardFocused(): void {
    setAutoFocusBoard(false);
    setStartButtonVisible(false);
  }

  function onComplete(completed: TournamentResult): void {
    setTournament((previous) => previous ? recordTournamentResult(previous, completed) : previous);
  }

  function turnAction(): void {
    if (!tournament) return;
    if (match?.winner) {
      setTournament(advanceTournamentMatch(tournament));
      resetTurnView();
    } else if (current?.turn === 0 && match?.results[0]) {
      setTournament(advanceTournamentTurn(tournament));
      resetTurnView();
    } else if (!turnStarted) startTurn();
  }

  function resetTurnView(): void {
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setGameFeedback({ key: '', number: 0, text: '' });
    clearNotice();
  }

  function exportCurrent(): void {
    const selectedTournament = tournament ?? history[0] ?? null;
    let snapshot: string | null = null;
    if (tournament && result === null && turnStarted) snapshot = turn.current?.exportSnapshot() ?? null;
    const output = encodeTournament({ draft, gameSnapshot: snapshot, tournament: selectedTournament });
    if (new TextEncoder().encode(output).byteLength > TOURNAMENT_MAX_BYTES) {
      publish('Tournament export is too large.');
      return;
    }
    setJson(output);
    publish('Tournament exported to the JSON box.');
  }

  function loadFromJson(): void {
    const transfer = decodeTournament(json);
    if (!transfer) {
      publish('Invalid tournament JSON.');
      return;
    }
    if (tournament?.status === 'active') {
      setPendingTransfer(transfer);
      setDialogAction('load');
      return;
    }
    applyTransfer(transfer);
  }

  function applyTransfer(transfer: NonNullable<ReturnType<typeof decodeTournament>>): void {
    setDraft(transfer.draft);
    setTournament(transfer.tournament);
    setGameSnapshot(transfer.gameSnapshot);
    setTurnStarted(transfer.gameSnapshot !== null);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setSaveWhenComplete(false);
    setGameFeedback({ key: '', number: 0, text: '' });
    publish('Tournament loaded.');
  }

  function requestLeave(): void {
    setDialogAction('leave');
  }

  function cancelDialog(): void {
    setDialogAction(null);
    setPendingTransfer(null);
  }

  function confirmDialog(): void {
    const action = dialogAction;
    setDialogAction(null);
    if (action === 'leave') {
      setTournament(null);
      setGameSnapshot(null);
      setTurnStarted(false);
      setSaveWhenComplete(false);
      onBack();
      return;
    }
    if (action === 'load' && pendingTransfer) applyTransfer(pendingTransfer);
    setPendingTransfer(null);
  }

  const actionLabel = tournament?.status === 'active'
    ? match?.winner
      ? 'Next match'
      : current?.turn === 0 && match?.results[0]
        ? 'Next turn'
        : !turnStarted || startButtonVisible
          ? 'Start turn'
          : null
    : null;
  const status = makeStatus(tournament, player, match, current, result, gameFeedback, activeTurnKey, notice.message);
  const statusKey = makeStatusKey(
    tournament,
    player,
    match,
    current,
    result,
    gameFeedback,
    activeTurnKey,
    notice,
  );

  return {
    actionLabel,
    activeTurnKey,
    autoFocusBoard,
    cancelDialog,
    confirmDialog,
    current,
    dialogAction,
    draft,
    exportCurrent,
    gameSnapshot,
    history,
    json,
    loadFromJson,
    match,
    notice: notice.message,
    onBoardFocused,
    onComplete,
    onFeedback,
    player,
    requestLeave,
    result,
    setDraft,
    setJson,
    startButtonVisible,
    startTournament,
    status,
    statusKey,
    storageAvailable,
    tournament,
    turn,
    turnAction,
    turnStarted,
  };
}

function makeStatus(
  tournament: Tournament | null,
  player: Tournament['entrants'][number] | null,
  match: ReturnType<typeof currentMatch>,
  current: Tournament['current'],
  result: TournamentResult | null,
  feedback: GameFeedback,
  turnKey: string,
  notice: string,
): string {
  let base = '';
  if (tournament?.status === 'complete' && tournament.champion) base = `Champion: ${tournament.champion.name}.`;
  else if (tournament?.status === 'active' && match?.winner) base = `Match winner: ${match.winner.name}.`;
  else if (player && result) base = `${player.name} finished. Select ${current?.turn === 0 ? 'Next turn' : 'Next match'}.`;
  else if (player) base = `Now playing: ${player.name}${feedback.key === turnKey && feedback.text ? `. ${feedback.text}` : ''}`;
  if (notice) return base ? `${notice} ${base}` : notice;
  return base;
}

function makeStatusKey(
  tournament: Tournament | null,
  player: Tournament['entrants'][number] | null,
  match: ReturnType<typeof currentMatch>,
  current: Tournament['current'],
  result: TournamentResult | null,
  feedback: GameFeedback,
  turnKey: string,
  notice: TournamentNotice,
): string {
  if (notice.message) return `notice-${notice.number}-${turnKey}-${feedback.key === turnKey ? feedback.number : 0}`;
  if (tournament?.status === 'complete') return `champion-${tournament.champion?.seed ?? 0}`;
  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}

