import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { SyntheticEvent } from 'react';
import { parseBoardCode } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { TournamentTurn, type TournamentTurnHandle } from './TournamentTurn.tsx';
import { decodeTournament, encodeTournament, TOURNAMENT_MAX_BYTES } from './tournament-format.ts';
import {
  acceptPlayerNames,
  advanceTournamentMatch,
  advanceTournamentTurn,
  createTournament,
  currentMatch,
  currentPlayer,
  currentResult,
  recordTournamentResult,
  roundDefinitions,
  type Tournament,
  type TournamentDraft,
  type TournamentResult,
} from './tournament.ts';
import {
  browserTournamentStore,
  readTournamentHistory,
  writeTournamentHistory,
  type TournamentStore,
} from './tournament-storage.ts';
import './tournament.css';
import '../controls/control.css';

interface TournamentProps {
  readonly onBack: () => void;
}

type DialogAction = 'leave' | 'load' | null;

const EMPTY_DRAFT: TournamentDraft = { playerCount: 4, players: ['', '', '', '', '', '', '', ''] };

export function Tournament({ onBack }: TournamentProps) {
  const [store] = useState<TournamentStore | null>(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState<readonly Tournament[]>(initialHistory.items);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const [draft, setDraft] = useState<TournamentDraft>(EMPTY_DRAFT);
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [gameSnapshot, setGameSnapshot] = useState<string | null>(null);
  const [turnStarted, setTurnStarted] = useState(false);
  const [startButtonVisible, setStartButtonVisible] = useState(false);
  const [autoFocusBoard, setAutoFocusBoard] = useState(false);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [noticeNumber, setNoticeNumber] = useState(0);
  const [gameFeedback, setGameFeedback] = useState({ key: '', number: 0, text: '' });
  const [saveWhenComplete, setSaveWhenComplete] = useState(false);
  const [dialogAction, setDialogAction] = useState<DialogAction>(null);
  const [pendingTransfer, setPendingTransfer] = useState<ReturnType<typeof decodeTournament>>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const championRef = useRef<HTMLParagraphElement>(null);
  const priorTournamentStatus = useRef<Tournament['status'] | null>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const turn = useRef<TournamentTurnHandle>(null);
  const turnKeyRef = useRef('');

  useLayoutEffect(() => {
    heading.current?.focus();
  }, []);

  useLayoutEffect(() => {
    if (tournament?.status === 'complete' && priorTournamentStatus.current !== 'complete')
      championRef.current?.focus();
    priorTournamentStatus.current = tournament?.status ?? null;
  }, [tournament?.status]);

  useEffect(() => {
    const element = dialog.current;
    if (dialogAction && element && !element.open) element.showModal();
    if (!dialogAction && element?.open) element.close();
  }, [dialogAction]);

  useEffect(() => {
    if (!saveWhenComplete || tournament?.status !== 'complete') return;
    const next = [tournament, ...history].slice(0, 10);
    setHistory(next);
    setStorageAvailable(writeTournamentHistory(store, next));
    setSaveWhenComplete(false);
  }, [history, saveWhenComplete, store, tournament]);

  const current = tournament?.current ?? null;
  const match = tournament ? currentMatch(tournament) : null;
  const player = tournament ? currentPlayer(tournament) : null;
  const result = tournament ? currentResult(tournament) : null;
  const activeTurnKey = current ? `${current.round}-${current.match}-${current.turn}` : '';
  turnKeyRef.current = activeTurnKey;

  const onFeedback = useCallback((text: string, number: number) => {
    setGameFeedback({ key: turnKeyRef.current, number, text });
  }, []);

  function publish(message: string): void {
    setNotice(message);
    setNoticeNumber((number) => number + 1);
  }

  function clearNotice(): void {
    setNotice('');
  }

  function startTournament(): void {
    const accepted = acceptPlayerNames(draft.players, draft.playerCount);
    if (!('names' in accepted)) {
      publish(accepted.error);
      return;
    }
    const sizes = roundDefinitions(draft.playerCount).flatMap((round) =>
      Array.from({ length: round.matchCount }, () => round.size),
    );
    const boardCodes: string[] = [];
    const usedCodes = new Set<string>();
    let previousSeed: number | undefined;
    for (const size of sizes) {
      let code = freshBoardCode(size, previousSeed);
      while (usedCodes.has(code)) code = freshBoardCode(size, previousSeed);
      usedCodes.add(code);
      boardCodes.push(code);
      previousSeed = parseBoardCode(code)?.seed;
    }
    const next = createTournament(draft.playerCount, accepted.names, boardCodes);
    if (!next) {
      publish('Could not start tournament.');
      return;
    }
    const players = [...draft.players];
    accepted.names.forEach((name, index) => { players[index] = name; });
    setDraft({ ...draft, players });
    setTournament(next);
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setSaveWhenComplete(true);
    setNotice('');
    setGameFeedback({ key: '', number: 0, text: '' });
  }

  function startTurn(): void {
    setGameSnapshot(null);
    setTurnStarted(true);
    setStartButtonVisible(true);
    setAutoFocusBoard(true);
    clearNotice();
  }

  function onBoardFocused(): void {
    setAutoFocusBoard(false);
    setStartButtonVisible(false);
  }

  function completeTurn(completed: TournamentResult): void {
    setTournament((previous) => previous ? recordTournamentResult(previous, completed) : previous);
  }

  function nextTurn(): void {
    if (!tournament) return;
    setTournament(advanceTournamentTurn(tournament));
    resetTurnView();
  }

  function nextMatch(): void {
    if (!tournament) return;
    setTournament(advanceTournamentMatch(tournament));
    resetTurnView();
  }

  function resetTurnView(): void {
    setGameSnapshot(null);
    setTurnStarted(false);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setGameFeedback({ key: '', number: 0, text: '' });
    clearNotice();
  }

  function exportCurrent(): void {
    const selectedTournament = tournament ?? history[0] ?? null;
    let snapshot: string | null = null;
    if (tournament && result === null && turnStarted) snapshot = turn.current?.exportSnapshot() ?? null;
    const output = encodeTournament({ draft, gameSnapshot: snapshot, tournament: selectedTournament });
    if (new TextEncoder().encode(output).byteLength > TOURNAMENT_MAX_BYTES) {
      publish('Tournament export is too large.');
      return;
    }
    setJson(output);
    publish('Tournament exported to the JSON box.');
  }

  function loadFromJson(): void {
    const transfer = decodeTournament(json);
    if (!transfer) {
      publish('Invalid tournament JSON.');
      return;
    }
    if (tournament?.status === 'active') {
      setPendingTransfer(transfer);
      setDialogAction('load');
      return;
    }
    applyTransfer(transfer);
  }

  function applyTransfer(transfer: NonNullable<ReturnType<typeof decodeTournament>>): void {
    setDraft(transfer.draft);
    setTournament(transfer.tournament);
    setGameSnapshot(transfer.gameSnapshot);
    setTurnStarted(transfer.gameSnapshot !== null);
    setStartButtonVisible(false);
    setAutoFocusBoard(false);
    setSaveWhenComplete(false);
    setGameFeedback({ key: '', number: 0, text: '' });
    publish('Tournament loaded.');
  }

  function confirmDialog(): void {
    const action = dialogAction;
    setDialogAction(null);
    if (action === 'leave') {
      setTournament(null);
      setGameSnapshot(null);
      setTurnStarted(false);
      setSaveWhenComplete(false);
      onBack();
      return;
    }
    if (action === 'load' && pendingTransfer) applyTransfer(pendingTransfer);
    setPendingTransfer(null);
  }

  function requestLeave(): void {
    setDialogAction('leave');
  }

  function cancelDialog(event: SyntheticEvent<HTMLDialogElement>): void {
    event.preventDefault();
    setDialogAction(null);
    setPendingTransfer(null);
  }

  const status = statusText(tournament, player, match, current, result, gameFeedback, activeTurnKey, notice);
  const statusKey = statusEventKey(
    tournament,
    player,
    match,
    current,
    result,
    gameFeedback,
    activeTurnKey,
    noticeNumber,
    notice,
  );
  const actionLabel = tournament?.status === 'active'
    ? match?.winner
      ? 'Next match'
      : current?.turn === 0 && match?.results[0]
        ? 'Next turn'
        : !turnStarted || startButtonVisible
          ? 'Start turn'
          : null
    : null;

  return (
    <main className="tournament-screen">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} className="tournament-title" tabIndex={-1}>Tournament</h2>
      <p className="tournament-live" role="status" aria-live="polite" aria-atomic="true">
        <span key={statusKey}>{status}</span>
      </p>
      {tournament?.status === 'complete' && tournament.champion && (
        <div className="tournament-champion">
          <p ref={championRef} tabIndex={-1}><strong>Champion: {tournament.champion.name}</strong></p>
          <button className="control" type="button" onClick={onBack}>Back to game</button>
        </div>
      )}
      {!tournament && (
        <TournamentSetup draft={draft} onDraftChange={setDraft} onStart={startTournament} onBack={onBack} />
      )}
      {tournament?.status === 'active' && current && match && player && (
        <section className="tournament-play" aria-labelledby="tournament-play-title">
          <h3 id="tournament-play-title">Tournament match</h3>
          <p className="tournament-round">Round: {tournament.rounds[current.round]?.name}</p>
          <div className="tournament-action-row">
            {actionLabel && (
              <button
                className="control"
                type="button"
                onClick={actionLabel === 'Next turn' ? nextTurn : actionLabel === 'Next match' ? nextMatch : startTurn}
              >
                {actionLabel}
              </button>
            )}
            <button className="control" type="button" onClick={requestLeave}>Leave tournament</button>
          </div>
          {turnStarted && (
            <TournamentTurn
              key={`${activeTurnKey}-${gameSnapshot ?? 'fresh'}`}
              ref={turn}
              autoFocusBoard={autoFocusBoard}
              boardCode={match.boardCode}
              initialSnapshot={gameSnapshot}
              onBoardFocused={onBoardFocused}
              onComplete={completeTurn}
              onFeedback={onFeedback}
              player={player}
            />
          )}
          <TournamentBracket current={current} rounds={tournament.rounds} />
        </section>
      )}
      {tournament?.status === 'complete' && (
        <TournamentBracket current={null} rounds={tournament.rounds} />
      )}
      <section className="tournament-exchange" aria-labelledby="tournament-json-title">
        <h3 id="tournament-json-title">Tournament data</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control tournament-json"
          value={json}
          maxLength={65_536}
          spellCheck={false}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportCurrent}>Export tournament</button>
          <button className="control" type="button" onClick={loadFromJson}>Load tournament</button>
        </div>
      </section>
      <section className="tournament-history" aria-labelledby="tournament-history-title">
        <h3 id="tournament-history-title">Past tournaments</h3>
        {!storageAvailable && <p className="tournament-storage-warning">Progress won't be saved on this device.</p>}
        {history.length === 0 ? (
          <p>No finished tournaments yet.</p>
        ) : (
          <ol>
            {history.map((past, index) => (
              <li key={`${past.playerCount}-${past.champion?.seed ?? 0}-${index}`}>
                <details>
                  <summary>{past.playerCount} players · Champion: {past.champion?.name}</summary>
                  <TournamentBracket current={null} rounds={past.rounds} />
                </details>
              </li>
            ))}
          </ol>
        )}
      </section>
      {tournament?.status === 'active' && (
        <dialog ref={dialog} className="tournament-dialog" onCancel={cancelDialog}>
          <h3>Leave this unfinished tournament?</h3>
          <p>Your current tournament will stop.</p>
          <div className="tournament-actions">
            <button className="control" type="button" autoFocus onClick={() => setDialogAction(null)}>
              Keep playing
            </button>
            <button className="control" type="button" onClick={confirmDialog}>Leave</button>
          </div>
        </dialog>
      )}
    </main>
  );
}

function statusText(
  tournament: Tournament | null,
  player: Tournament['entrants'][number] | null,
  match: ReturnType<typeof currentMatch>,
  current: Tournament['current'],
  result: TournamentResult | null,
  feedback: { readonly key: string; readonly text: string },
  turnKey: string,
  notice: string,
): string {
  let base = '';
  if (tournament?.status === 'complete' && tournament.champion) base = `Champion: ${tournament.champion.name}.`;
  else if (tournament?.status === 'active' && match?.winner) base = `Match winner: ${match.winner.name}.`;
  else if (player && result) base = `${player.name} finished. Select ${current?.turn === 0 ? 'Next turn' : 'Next match'}.`;
  else if (player) base = `Now playing: ${player.name}${feedback.key === turnKey && feedback.text ? `. ${feedback.text}` : ''}`;
  if (notice) return base ? `${notice} ${base}` : notice;
  return base;
}

function statusEventKey(
  tournament: Tournament | null,
  player: Tournament['entrants'][number] | null,
  match: ReturnType<typeof currentMatch>,
  current: Tournament['current'],
  result: TournamentResult | null,
  feedback: { readonly key: string; readonly number: number },
  turnKey: string,
  noticeNumber: number,
  notice: string,
): string {
  if (notice) return `notice-${noticeNumber}-${turnKey}-${feedback.key === turnKey ? feedback.number : 0}`;
  if (tournament?.status === 'complete') return `champion-${tournament.champion?.seed ?? 0}`;
  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}

