import { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState } from 'react';
import { parseBoardCode } from '../deck.ts';
import { isWon } from '../game.ts';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { encodeSnapshot, decodeSnapshot } from '../snapshot.ts';
import { initialSession, activateSession } from '../session/session.ts';
import { useSessionClock } from '../session/use-session-clock.ts';
import type { Session } from '../session/session.ts';
import type { TournamentPlayer, TournamentResult } from './tournament.ts';

export interface TournamentTurnHandle {
  exportSnapshot(): string;
}

interface TournamentTurnProps {
  readonly autoFocusBoard: boolean;
  readonly boardCode: string;
  readonly initialSnapshot: string | null;
  readonly onBoardFocused: () => void;
  readonly onComplete: (result: TournamentResult) => void;
  readonly onFeedback: (feedback: string, announcement: number) => void;
  readonly player: TournamentPlayer;
}

export const TournamentTurn = forwardRef<TournamentTurnHandle, TournamentTurnProps>(
  function TournamentTurn(
    { autoFocusBoard, boardCode, initialSnapshot, onBoardFocused, onComplete, onFeedback, player },
    ref,
  ) {
    const [session, setSession] = useState(() => createTurnSession(boardCode, initialSnapshot));
    const current = useRef(session);
    const board = useRef<BoardFocus>(null);
    const onCompleteRef = useRef(onComplete);
    const onFeedbackRef = useRef(onFeedback);
    const onBoardFocusedRef = useRef(onBoardFocused);
    onCompleteRef.current = onComplete;
    onFeedbackRef.current = onFeedback;
    onBoardFocusedRef.current = onBoardFocused;

    function commit(next: Session): void {
      if (next === current.current) return;
      current.current = next;
      setSession(next);
    }

    const clock = useSessionClock(session, current, commit);
    const synchronizeRef = useRef(clock.synchronize);
    synchronizeRef.current = clock.synchronize;

    useImperativeHandle(
      ref,
      () => ({
        exportSnapshot() {
          synchronizeRef.current();
          return encodeSnapshot(current.current.game);
        },
      }),
      [],
    );

    useLayoutEffect(() => {
      if (!autoFocusBoard) return;
      board.current?.focusRemembered();
      onBoardFocusedRef.current();
    }, [autoFocusBoard]);

    useEffect(() => {
      if (session.announcement > 0 && session.feedback)
        onFeedbackRef.current(session.feedback, session.announcement);
    }, [session.announcement, session.feedback]);

    useEffect(() => {
      if (isWon(session.game))
        onCompleteRef.current({ elapsedMs: session.game.elapsedMs, moves: session.game.moves });
    }, [session.game.elapsedMs, session.game.matched.length, session.game.moves]);

    function activate(index: number): void {
      clock.synchronize();
      commit(activateSession(current.current, index));
    }

    return (
      <section className="tournament-turn" aria-labelledby="tournament-turn-title">
        <h3 id="tournament-turn-title">{player.name}'s game</h3>
        <GameStatus game={session.game} best={undefined} celebration={false} showBest={false} />
        <p id="board-help" className="help">
          Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
        </p>
        <Board
          key={session.generation}
          game={session.game}
          activate={activate}
          ref={board}
        />
      </section>
    );
  },
);

function createTurnSession(boardCode: string, snapshotText: string | null): Session {
  const restored = snapshotText ? decodeSnapshot(snapshotText) : null;
  const size = restored?.size ?? parseBoardCode(boardCode)?.size ?? 4;
  const session = initialSession(boardCode, { size, bestMoves: {} });
  return restored?.boardCode === boardCode ? { ...session, game: restored } : session;
}
import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import { faceUpCards } from '../game.ts';
import { Card } from './Card.tsx';
import { useBoardFocus } from './use-board-focus.ts';
import type { CSSProperties, RefObject } from 'react';
import type { GameState } from '../game.ts';
import './board.css';

interface BoardProps {
  game: GameState;
  ref: RefObject<BoardFocus | null>;
  activate(index: number): void;
}
const NEAREST: ScrollIntoViewOptions = { block: 'nearest', inline: 'nearest' };
interface BoardStyle extends CSSProperties {
  '--grid-size': number;
}

export interface BoardFocus {
  focusRemembered(): void;
}

// Once a click or tap completes, the focused card can move fully into view.
function cardClicked(card: HTMLElement): void {
  card.scrollIntoView(NEAREST);
}

export function Board({ game, ref, activate }: BoardProps) {
  const { size, deck, matched, selection } = game;
  const { viewport, element, focused, focusRemembered, navigate, cardFocused } =
    useBoardFocus(size);
  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
  const matchedCards = useMemo(() => new Set(matched), [matched]);
  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
  const latestActivate = useRef(activate);
  useLayoutEffect(() => {
    latestActivate.current = activate;
  });
  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
  const style: BoardStyle = { '--grid-size': size };
  return (
    <div
      ref={viewport}
      className="board-viewport"
      role="region"
      aria-label="Game board"
      aria-describedby="board-help"
    >
      <div className="board" ref={element} style={style}>
        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            clicked={cardClicked}
            navigate={navigate}
          />
        ))}
      </div>
    </div>
  );
}

import { isWon } from '../game.ts';
import { decodeSnapshot, SNAPSHOT_MAX_BYTES } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { currentMatch, isPlayerCount, type Tournament, type TournamentDraft } from './tournament.ts';
import { isValidTournament } from './tournament-validation.ts';

export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FORMAT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 65_536;

export interface TournamentTransfer {
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly tournament: Tournament | null;
}

export function encodeTournament(transfer: TournamentTransfer): string {
  const value = {
    draft: transfer.draft,
    format: TOURNAMENT_FORMAT,
    gameSnapshot: transfer.gameSnapshot,
    tournament: transfer.tournament,
    version: TOURNAMENT_FORMAT_VERSION,
  };
  return JSON.stringify(sortKeys(value), null, 2);
}

export function decodeTournament(text: string): TournamentTransfer | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['draft', 'format', 'gameSnapshot', 'tournament', 'version']) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    !validDraft(value.draft)
  )
    return null;
  if (value.tournament !== null && !isValidTournament(value.tournament)) return null;
  if (value.gameSnapshot !== null && typeof value.gameSnapshot !== 'string') return null;
  if (typeof value.gameSnapshot === 'string') {
    if (value.gameSnapshot.length > SNAPSHOT_MAX_BYTES) return null;
    const game = decodeSnapshot(value.gameSnapshot);
    const tournament = value.tournament as Tournament | null;
    const match = tournament ? currentMatch(tournament) : null;
    const position = tournament?.current;
    if (
      !game ||
      !tournament ||
      tournament.status !== 'active' ||
      !position ||
      !match ||
      match.results[position.turn] !== null ||
      game.boardCode !== match.boardCode
    )
      return null;
    // A completed snapshot is allowed only for the current unfinished attempt. Loading it will
    // record the same visible result through the ordinary completion boundary.
    if (isWon(game) && !game.started) return null;
  }
  return {
    draft: value.draft,
    gameSnapshot: value.gameSnapshot,
    tournament: value.tournament as Tournament | null,
  };
}

function validDraft(value: unknown): value is TournamentDraft {
  return (
    isJsonObject(value) &&
    hasExactKeys(value, ['playerCount', 'players']) &&
    typeof value.playerCount === 'number' &&
    isPlayerCount(value.playerCount) &&
    Array.isArray(value.players) &&
    value.players.length === 8 &&
    value.players.every((name) => typeof name === 'string')
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) sorted[key] = sortKeys((value as Record<string, unknown>)[key]);
  return sorted;
}
