import { formatElapsed } from '../elapsed-time.ts';
import { currentMatch } from './tournament.ts';
import type { Tournament, TournamentPlayer, TournamentPosition, TournamentResult } from './tournament.ts';

export interface TournamentFeedback {
  readonly key: string;
  readonly number: number;
  readonly text: string;
}

export interface TournamentNotice {
  readonly message: string;
  readonly number: number;
}

export function tournamentStatusText(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: string,
): string {
  let base = '';
  if (tournament?.status === 'complete' && tournament.champion) {
    const final = tournament.rounds.at(-1)?.matches[0];
    const championIndex = final?.players.findIndex((entrant) => entrant?.seed === tournament.champion?.seed) ?? -1;
    const championResult = final?.results[championIndex];
    base = championResult
      ? `Champion: ${tournament.champion.name}. ${championResult.moves} moves in ${formatElapsed(championResult.elapsedMs)}.`
      : `Champion: ${tournament.champion.name}.`;
  } else if (player && result) {
    const finished = `${player.name} finished with ${result.moves} moves in ${formatElapsed(result.elapsedMs)}.`;
    base = match?.winner
      ? `${finished} Match winner: ${match.winner.name}.`
      : `${finished} Select ${current?.turn === 0 ? 'Next turn' : 'Next match'}.`;
  } else if (player) {
    base = `Now playing: ${player.name}${feedback.key === turnKey && feedback.text ? `. ${feedback.text}` : ''}`;
  }
  if (notice) return base ? `${notice} ${base}` : notice;
  return base;
}

export function tournamentStatusKey(
  tournament: Tournament | null,
  player: TournamentPlayer | null,
  match: ReturnType<typeof currentMatch>,
  current: TournamentPosition | null,
  result: TournamentResult | null,
  feedback: TournamentFeedback,
  turnKey: string,
  notice: TournamentNotice,
): string {
  if (notice.message) return `notice-${notice.number}-${turnKey}-${feedback.key === turnKey ? feedback.number : 0}`;
  if (tournament?.status === 'complete') return `champion-${tournament.champion?.seed ?? 0}`;
  if (match?.winner) return `match-${current?.round}-${current?.match}-winner`;
  if (result) return `finish-${current?.round}-${current?.match}-${current?.turn}`;
  return `${turnKey}-${feedback.key === turnKey ? feedback.number : 0}-${player?.seed ?? 0}`;
}
import { useLayoutEffect, useRef } from 'react';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentTurn } from './TournamentTurn.tsx';
import type { TournamentController } from './use-tournament.ts';

interface TournamentProgressProps {
  readonly controller: TournamentController;
}

export function TournamentProgress({ controller }: TournamentProgressProps) {
  const { current, match, player, tournament } = controller;
  const action = useRef<HTMLButtonElement>(null);
  const previousAction = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (controller.actionLabel === 'Start turn' && previousAction.current !== 'Start turn')
      action.current?.focus();
    previousAction.current = controller.actionLabel;
  }, [controller.actionLabel]);
  if (tournament?.status !== 'active' || !current || !match || !player) return null;
  return (
    <section className="tournament-play" aria-labelledby="tournament-play-title">
      <h3 id="tournament-play-title">Tournament match</h3>
      <p className="tournament-round">Round: {tournament.rounds[current.round]?.name}</p>
      <div className="tournament-action-row">
        {controller.actionLabel && (
          <button ref={action} className="control" type="button" onClick={controller.turnAction}>
            {controller.actionLabel}
          </button>
        )}
        <button className="control" type="button" onClick={controller.requestLeave}>Leave tournament</button>
      </div>
      {controller.turnStarted && (
        <TournamentTurn
          key={`${controller.activeTurnKey}-${controller.gameSnapshot ?? 'fresh'}`}
          ref={controller.turn}
          autoFocusBoard={controller.autoFocusBoard}
          boardCode={match.boardCode}
          initialSnapshot={controller.gameSnapshot}
          onBoardFocused={controller.onBoardFocused}
          onComplete={controller.onComplete}
          onFeedback={controller.onFeedback}
          player={player}
        />
      )}
      <TournamentBracket current={current} rounds={tournament.rounds} />
    </section>
  );
}
import { useEffect, useRef } from 'react';
import type { SyntheticEvent } from 'react';

interface TournamentDialogProps {
  readonly action: 'leave' | 'load' | null;
  readonly onCancel: () => void;
  readonly onConfirm: () => void;
  readonly open: boolean;
}

export function TournamentDialog({ action, open, onCancel, onConfirm }: TournamentDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const element = dialog.current;
    if (open && element && !element.open) element.showModal();
    if (!open && element?.open) element.close();
  }, [open]);

  function cancel(event: SyntheticEvent<HTMLDialogElement>): void {
    event.preventDefault();
    onCancel();
  }

  return (
    <dialog
      ref={dialog}
      className="tournament-dialog"
      aria-labelledby="tournament-dialog-title"
      aria-describedby="tournament-dialog-description"
      onCancel={cancel}
    >
      <h3 id="tournament-dialog-title">
        {action === 'load' ? 'Load another tournament?' : 'Leave this unfinished tournament?'}
      </h3>
      <p id="tournament-dialog-description">
        {action === 'load'
          ? 'Your current tournament will be replaced by the tournament in the JSON box.'
          : 'Your current tournament will stop.'}
      </p>
      <div className="tournament-actions">
        <button className="control" type="button" autoFocus onClick={onCancel}>Keep playing</button>
        <button className="control" type="button" onClick={onConfirm}>
          {action === 'load' ? 'Load tournament' : 'Leave'}
        </button>
      </div>
    </dialog>
  );
}

