    !isJsonObject(value) ||
    !hasExactKeys(value, ['draft', 'format', 'gameSnapshot', 'tournament', 'version']) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    !validDraft(value.draft)
