  const current = readTournamentCurrent(value.current, rounds);
  if (champion === undefined || current === undefined) return false;
  const tournament = {
    champion,
    current,
    entrants: validEntrants,
    playerCount,
    rounds,
    status: value.status,
  } as Tournament;
  return validTournamentProgress(tournament);
}

