export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FORMAT_VERSION = 1;
export const TOURNAMENT_MAX_BYTES = 65_536;

export interface TournamentTransfer {
  readonly draft: TournamentDraft;
  readonly gameSnapshot: string | null;
  readonly tournament: Tournament | null;
}

export function encodeTournament(transfer: TournamentTransfer): string {
  const value = {
    draft: transfer.draft,
    format: TOURNAMENT_FORMAT,
    gameSnapshot: transfer.gameSnapshot,
    tournament: transfer.tournament,
    version: TOURNAMENT_FORMAT_VERSION,
  };
  return JSON.stringify(sortKeys(value), null, 2);
}

export function decodeTournament(text: string): TournamentTransfer | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['draft', 'format', 'gameSnapshot', 'tournament', 'version']) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    !validDraft(value.draft)
  )
    return null;
  if (value.tournament !== null && !isValidTournament(value.tournament)) return null;
  if (value.gameSnapshot !== null && typeof value.gameSnapshot !== 'string') return null;
  if (typeof value.gameSnapshot === 'string') {
    if (value.gameSnapshot.length > SNAPSHOT_MAX_BYTES) return null;
    const game = decodeSnapshot(value.gameSnapshot);
    const tournament = value.tournament as Tournament | null;
    const match = tournament ? currentMatch(tournament) : null;
    const position = tournament?.current;
    if (
      !game ||
      !tournament ||
      tournament.status !== 'active' ||
      !position ||
      !match ||
      match.results[position.turn] !== null ||
      game.boardCode !== match.boardCode
    )
      return null;
    // A completed snapshot is allowed only for the current unfinished attempt. Loading it will
    // record the same visible result through the ordinary completion boundary.
    if (isWon(game) && !game.started) return null;
  }
  return {
    draft: value.draft,
    gameSnapshot: value.gameSnapshot,
    tournament: value.tournament as Tournament | null,
  };
}

function validDraft(value: unknown): value is TournamentDraft {
  return (
    isJsonObject(value) &&
    hasExactKeys(value, ['playerCount', 'players']) &&
    typeof value.playerCount === 'number' &&
    isPlayerCount(value.playerCount) &&
    Array.isArray(value.players) &&
    value.players.length === 8 &&
    value.players.every((name) => typeof name === 'string')
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  const sorted: Record<string, unknown> = {};
  for (const key of Object.keys(value).sort()) sorted[key] = sortKeys((value as Record<string, unknown>)[key]);
  return sorted;
}
import { hasExactKeys, isJsonObject } from '../saved-format.ts';
import { roundDefinitions, type Tournament, type TournamentPlayer, type TournamentPlayerCount, type TournamentRound } from './tournament.ts';
import {
  readTournamentCurrent,
  readTournamentMatch,
  readTournamentPlayer,
  validTournamentPairings,
  validTournamentProgress,
} from './tournament-validation-entries.ts';

export function isValidTournament(value: unknown): value is Tournament {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['champion', 'current', 'entrants', 'playerCount', 'rounds', 'status']) ||
    (value.playerCount !== 4 && value.playerCount !== 8) ||
    (value.status !== 'active' && value.status !== 'complete') ||
    !Array.isArray(value.entrants) ||
    !Array.isArray(value.rounds)
  )
    return false;
  const playerCount = value.playerCount as TournamentPlayerCount;
  if (value.entrants.length !== playerCount) return false;
  const entrants = value.entrants.map((entry) => readTournamentPlayer(entry, playerCount));
  if (entrants.some((entry) => entry === undefined)) return false;
  const validEntrants = entrants as TournamentPlayer[];
  if (validEntrants.some((entry, index) => entry.seed !== index + 1)) return false;
  if (new Set(validEntrants.map((entry) => entry.name.toLowerCase())).size !== playerCount) return false;

  const definitions = roundDefinitions(playerCount);
  if (value.rounds.length !== definitions.length) return false;
  const usedCodes = new Set<string>();
  const rounds: TournamentRound[] = [];
  for (let roundIndex = 0; roundIndex < definitions.length; roundIndex += 1) {
    const rawRound = value.rounds[roundIndex];
    const definition = definitions[roundIndex]!;
    if (
      !isJsonObject(rawRound) ||
      !hasExactKeys(rawRound, ['matches', 'name', 'size']) ||
      rawRound.name !== definition.name ||
      rawRound.size !== definition.size ||
      !Array.isArray(rawRound.matches) ||
      rawRound.matches.length !== definition.matchCount
    )
      return false;
    const matches: TournamentRound['matches'][number][] = [];
    for (const rawMatch of rawRound.matches) {
      const match = readTournamentMatch(rawMatch, playerCount, definition.size);
      if (!match || usedCodes.has(match.boardCode)) return false;
      usedCodes.add(match.boardCode);
      matches.push(match);
    }
    rounds.push({ matches, name: definition.name, size: definition.size });
  }
  if (!validTournamentPairings(validEntrants, rounds, playerCount)) return false;

  const champion = readTournamentPlayer(value.champion, playerCount, true);
  const current = readTournamentCurrent(value.current, rounds);
  if (champion === undefined || current === undefined) return false;
  const tournament = {
    champion,
    current,
    entrants: validEntrants,
    playerCount,
    rounds,
    status: value.status,
  } as Tournament;
  return validTournamentProgress(tournament);
}

